244	    private persistLastActivity(): void {
245	        // Build a per-project map of the maximum lastActivity timestamp.
246	        const maxByProject = new Map<string, string>();
247	
248	        for (const [repoPath, status] of this.cache) {
249	            if (status.lastActivity === null) {
250	                continue;
251	            }
252	            const context = extractContext(repoPath, this.config.projectsFolder);
253	            if (!context.ProjectId) {
254	                continue;
255	            }
256	            const projectId = context.ProjectId;
257	            const existing = maxByProject.get(projectId);
258	            // ISO 8601 strings with a consistent timezone offset (e.g. always 'Z')
259	            // sort correctly with lexicographic comparison.  All lastActivity values
260	            // originate from git commit timestamps normalised to a single offset, so
261	            // this comparison is safe.  Mixed offsets (e.g. 'Z' vs '+05:00') would
262	            // produce incorrect results — do not relax the normalisation constraint.
263	            if (existing === undefined || status.lastActivity > existing) {
264	                maxByProject.set(projectId, status.lastActivity);
265	            }
266	        }
